//
//  ANGReaderTests.swift
//  The .ang reader against orix 0.15.0 (`ang.file_reader`): every Fixtures/ebsd-*.ang reads with the values of
//  Fixtures/ebsd-edax.truth.json (tools/parity/sem-readers/make_edax_fixtures.py): vendor and column names, the header's grid, step
//  and projection centre, the map shape and step as CrystalMap derives them, the phase list (ids, autogenerated names, point groups
//  after orix's EDAX aliases, lattices), every column bit-equal through its sha256 (phase_id after the not-indexed convention), the
//  first and last row, and the rotations as quaternions within 1e-12 on sampled rows.
//

import CryptoKit
import TEMCore
import XCTest

nonisolated final class ANGReaderTests: XCTestCase {

    nonisolated struct Truth: Decodable {
        let fileSHA256: String
        let vendor: String
        let columns: [String]
        let nRows: Int
        let nColumns: Int
        let headerFields: [String: String]
        let shape: [Int]
        let dx: String
        let dy: String
        let scanUnit: String
        let phaseIDs: [Int]
        let phaseNames: [String]
        let pointGroups: [String?]
        let lattices: [[String]]
        let columnSHA256: [String: String]
        let firstRow: [String]
        let lastRow: [String]
        let phaseIDCounts: [String: Int]
        let notIndexed: Int
        let rotationSampleRows: [Int]
        let rotationSample: [String]
        let propNames: [String]
        enum CodingKeys: String, CodingKey {
            case vendor, columns, shape, dx, dy, lattices
            case fileSHA256 = "file_sha256", nRows = "n_rows", nColumns = "n_columns", headerFields = "header_fields", scanUnit = "scan_unit"
            case phaseIDs = "phase_ids", phaseNames = "phase_names", pointGroups = "point_groups", columnSHA256 = "column_sha256"
            case firstRow = "first_row", lastRow = "last_row", phaseIDCounts = "phase_id_counts", notIndexed = "not_indexed"
            case rotationSampleRows = "rotation_sample_rows", rotationSample = "rotation_sample", propNames = "prop_names"
        }
    }

    nonisolated struct TruthFile: Decodable {
        let orix: String
        let ang: [String: Truth]
    }

    static func truth() throws -> TruthFile {
        try JSONDecoder().decode(TruthFile.self, from: Data(contentsOf: EDAXBinaryReaderTests.fixture("ebsd-edax.truth.json")))
    }

    private func double(_ text: String, _ what: String) throws -> Double {
        try XCTUnwrap(Double(text), "\(what): '\(text)' is not a number")
    }

    private func assertClose(_ value: Double, _ text: String, _ what: String, file: StaticString = #filePath, line: UInt = #line) throws {
        let expected = try double(text, what)
        XCTAssertEqual(value, expected, accuracy: max(1e-12 * abs(expected), 1e-12), what, file: file, line: line)
    }

    private func bytes(_ values: [Double]) -> Data {
        var out = Data(capacity: values.count * 8)
        for value in values { withUnsafeBytes(of: value.bitPattern.littleEndian) { out.append(contentsOf: $0) } }
        return out
    }

    private func column(_ name: String, of file: ANGMap) -> [Double]? {
        let map = file.map
        switch name {
        case "euler1": return map.euler.map(\.x)
        case "euler2": return map.euler.map(\.y)
        case "euler3": return map.euler.map(\.z)
        case "x": return map.allX
        case "y": return map.allY
        case "phase_id": return map.phaseIDs.map(Double.init)
        default: return map.properties[name]
        }
    }

    func testTruthIsOrix0150() throws {
        let truth = try Self.truth()
        XCTAssertEqual(truth.orix, "0.15.0")
        XCTAssertEqual(Set(truth.ang.keys), ["ebsd-sdss-ferrite-austenite.ang", "ebsd-tsl.ang", "ebsd-tsl-hex.ang"])
    }

    func testEveryFixtureReadsAsOrixReadsIt() throws {
        for (name, expected) in try Self.truth().ang {
            let url = EDAXBinaryReaderTests.fixture(name)
            XCTAssertEqual(EDAXBinaryReaderTests.sha256(try Data(contentsOf: url)), expected.fileSHA256, "\(name): the fixture is not the one the truth was written from")
            let map = try ANGReader.read(url: url)
            XCTAssertEqual(map.vendor.rawValue, expected.vendor, "\(name) vendor")
            XCTAssertEqual(map.columnNames, expected.columns, "\(name) columns")
            XCTAssertEqual(map.pointCount, expected.nRows, "\(name) rows")
            XCTAssertEqual(map.columnNames.count, expected.nColumns, "\(name) column count")
            XCTAssertEqual(map.map.euler.count, expected.nRows, name)
            XCTAssertEqual(map.map.rotations.count, expected.nRows, name)
            XCTAssertEqual(map.map.phaseIDs.count, expected.nRows, name)
            // The header fields orix leaves in the file.
            XCTAssertEqual(map.header.grid, expected.headerFields["GRID"], "\(name) grid")
            func field(_ key: String) throws -> String { try XCTUnwrap(expected.headerFields[key], "\(name): no \(key) in the truth") }
            let stepX = try XCTUnwrap(map.header.stepX), stepY = try XCTUnwrap(map.header.stepY)
            try assertClose(stepX, try field("XSTEP"), "\(name) XSTEP")
            try assertClose(stepY, try field("YSTEP"), "\(name) YSTEP")
            let columnsOdd = Int(try field("NCOLS_ODD")), columnsEven = Int(try field("NCOLS_EVEN")), rows = Int(try field("NROWS"))
            XCTAssertEqual(map.header.columnsOdd, columnsOdd, "\(name) NCOLS_ODD")
            XCTAssertEqual(map.header.columnsEven, columnsEven, "\(name) NCOLS_EVEN")
            XCTAssertEqual(map.header.rows, rows, "\(name) NROWS")
            let pc = try XCTUnwrap(map.header.projectionCenter, "\(name) projection centre")
            try assertClose(pc.x, try field("x-star"), "\(name) x-star")
            try assertClose(pc.y, try field("y-star"), "\(name) y-star")
            try assertClose(pc.z, try field("z-star"), "\(name) z-star")
            let workingDistance = try XCTUnwrap(map.header.workingDistance), pixelsPerMicron = try XCTUnwrap(map.header.temPixelsPerMicron)
            try assertClose(workingDistance, try field("WorkingDistance"), "\(name) working distance")
            try assertClose(pixelsPerMicron, try field("TEM_PIXperUM"), "\(name) TEM_PIXperUM")
            XCTAssertEqual(map.header.lines.count, map.header.lines.filter { $0.hasPrefix("#") }.count, "\(name): header lines start with #")
            // The map as CrystalMap holds it.
            XCTAssertEqual(map.map.shape, expected.shape, "\(name) shape")
            try assertClose(map.map.dx, expected.dx, "\(name) dx")
            try assertClose(map.map.dy, expected.dy, "\(name) dy")
            XCTAssertEqual(map.map.scanUnit, expected.scanUnit, "\(name) scan unit")
            XCTAssertEqual(map.map.phases.ids, expected.phaseIDs, "\(name) phase ids")
            XCTAssertEqual(map.map.phases.names, expected.phaseNames, "\(name) phase names")
            XCTAssertEqual(map.map.phases.pointGroupNames, expected.pointGroups, "\(name) point groups")
            XCTAssertEqual(map.map.phases.count, expected.lattices.count, "\(name) lattices")
            for (phase, lattice) in zip(map.map.phases.phases, expected.lattices) {
                let ours = phase.lattice ?? []
                XCTAssertEqual(ours.count, lattice.count, "\(name) \(phase.name) lattice")
                for (value, text) in zip(ours, lattice) { try assertClose(value, text, "\(name) \(phase.name) lattice") }
            }
            for (columnName, sha) in expected.columnSHA256 {
                let values = try XCTUnwrap(column(columnName, of: map), "\(name): no column \(columnName)")
                XCTAssertEqual(EDAXBinaryReaderTests.sha256(bytes(values)), sha, "\(name) column \(columnName), bit for bit")
            }
            XCTAssertEqual(Set(map.map.properties.keys), Set(expected.propNames), "\(name) properties")
            let first = map.columnNames.map { column($0, of: map)![0] }
            let last = map.columnNames.map { column($0, of: map)![map.pointCount - 1] }
            // The first and last row as written (phase_id as written: orix's -1 is checked through the column sha and the counts).
            for (i, columnName) in map.columnNames.enumerated() where columnName != "phase_id" {
                try assertClose(first[i], expected.firstRow[i], "\(name) first row \(columnName)")
                try assertClose(last[i], expected.lastRow[i], "\(name) last row \(columnName)")
            }
            var counts: [String: Int] = [:]
            for id in map.map.phaseIDs { counts[String(id), default: 0] += 1 }
            XCTAssertEqual(counts, expected.phaseIDCounts, "\(name) phase id counts")
            XCTAssertEqual(map.notIndexedCount, expected.notIndexed, "\(name) not indexed")
            XCTAssertEqual(expected.rotationSample.count, expected.rotationSampleRows.count * 4, "\(name) truth rotations")
            for (k, row) in expected.rotationSampleRows.enumerated() {
                let q = map.map.rotations[row]
                for (j, component) in [q.x, q.y, q.z, q.w].enumerated() {
                    try assertClose(component, expected.rotationSample[4 * k + j], "\(name) rotation of row \(row), component \(j)")
                }
            }
        }
    }

    func testEulerToQuaternionIsRowenhorstEqA5() {
        let identity = ANGReader.quaternion(fromBungeEuler: .zero)
        XCTAssertEqual(identity, SIMD4(1, 0, 0, 0))
        // phi1 = pi: the scalar part would be cos(pi/2) = 0 and the last -sin(pi/2) = -1; a negative scalar flips the sign.
        let turned = ANGReader.quaternion(fromBungeEuler: SIMD3(Double.pi + 0.1, 0, 0))
        XCTAssertGreaterThanOrEqual(turned.x, 0)
        XCTAssertEqual(turned.x * turned.x + turned.y * turned.y + turned.z * turned.z + turned.w * turned.w, 1, accuracy: 1e-15)
    }

    func testHeaderParsingFollowsOrixsRegularExpressions() throws {
        // Names and formulas are read after one or more blanks; a header without Phase lines numbers the phases from 0; a second
        // Symmetry line without a MaterialName is a refusal, as PhaseList refuses it.
        let text = """
        # MaterialName  \tAlpha Beta
        # Formula   AB
        # Symmetry  62
        # LatticeConstants  2.95 2.95 4.68 90 90 120
        # GRID: SqrGrid
        0.1 0.2 0.3 0 0 10 0.5 0 100 0.1
        0.1 0.2 0.3 1 0 10 -1 0 100 0.1
        """
        let map = try ANGReader.read(text: text, url: URL(fileURLWithPath: "/tmp/a.ang"))
        XCTAssertEqual(map.vendor, .tsl)
        XCTAssertEqual(map.map.phases.ids, [-1, 0])
        XCTAssertEqual(map.map.phases.names, ["not_indexed", "AB"], "one formula per phase: the name becomes the formula")
        XCTAssertEqual(map.map.phases.pointGroupNames, [nil, "622"], "orix's alias of EDAX's 62")
        XCTAssertEqual(map.map.phases[id: 0]?.lattice, [2.95, 2.95, 4.68, 90, 90, 120])
        XCTAssertEqual(map.map.phases[id: 0]?.formula, "AB")
        XCTAssertEqual(map.map.phaseIDs, [0, -1], "confidence index -1 is not indexed")
        XCTAssertEqual(map.map.shape, [2], "one row of points: y does not vary")
        XCTAssertEqual(map.map.dx, 1)
        XCTAssertEqual(map.map.dy, 0)
        let noFormula = text.replacingOccurrences(of: "# Formula   AB\n", with: "")
        XCTAssertEqual(try ANGReader.read(text: noFormula, url: URL(fileURLWithPath: "/tmp/b.ang")).map.phases.names, ["not_indexed", "Alpha Beta"])
        let unknownSymmetry = text.replacingOccurrences(of: "# Symmetry  62", with: "# Symmetry  99")
        XCTAssertThrowsError(try ANGReader.read(text: unknownSymmetry, url: URL(fileURLWithPath: "/tmp/c.ang"))) { error in
            XCTAssertTrue(((error as? ANGReadError)?.text ?? "").contains("'99'"), String(describing: error))
        }
        let ragged = text + "0.1 0.2\n"
        XCTAssertThrowsError(try ANGReader.read(text: ragged, url: URL(fileURLWithPath: "/tmp/d.ang")))
        XCTAssertThrowsError(try ANGReader.read(text: "# GRID: SqrGrid\n", url: URL(fileURLWithPath: "/tmp/e.ang")))
    }

    func testAnUnexpectedColumnCountFallsBackToOrixsUnknownNames() throws {
        let text = "# Phase 1\n# MaterialName Ni\n# Symmetry 43\n# LatticeConstants 3.5 3.5 3.5 90 90 90\n" +
            "0.1 0.2 0.3 0 0 7 8 1 9 10 11\n0.1 0.2 0.3 1 0 7 8 1 9 10 11\n"
        let map = try ANGReader.read(text: text, url: URL(fileURLWithPath: "/tmp/f.ang"))
        XCTAssertEqual(map.vendor, .unknown, "11 columns match no EDAX variant")
        XCTAssertEqual(map.columnNames, ["euler1", "euler2", "euler3", "x", "y", "unknown1", "unknown2", "phase_id", "unknown3", "unknown4", "unknown5"])
        XCTAssertEqual(map.map.properties["unknown5"], [11, 11])
        XCTAssertEqual(map.map.phaseIDs, [1, 1], "no not-indexed convention for an unknown vendor")
        XCTAssertEqual(map.map.phases.names, ["Ni"], "no formula: the material name stays")
    }
}
